const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Pacific Palisades location and area north and west
  const pacificPalisades = ee.Geometry.Point([-118.54, 34.05]);
  const areaOfInterest = ee.Geometry.Polygon([
    [[-118.70, 34.05], [-118.70, 34.20], [-118.54, 34.20], [-118.54, 34.05], [-118.70, 34.05]]
  ]);

  // Function to mask clouds in Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to calculate NBR
  function addNBR(image) {
    const nbr = image.normalizedDifference(['B8', 'B12']).rename('NBR');
    return image.addBands(nbr);
  }

  // Get Sentinel-2 data for January 6, 2025
  let col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(areaOfInterest)
    .filterDate('2025-01-05', '2025-01-07')
    .map(maskS2clouds)
    .map(addNBR);

  const size1 = col1.size().getInfo();
  console.log(`Jan 6 Images: ${size1}`);

  if (size1 === 0) {
    col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(areaOfInterest)
      .filterDate('2025-01-04', '2025-01-08')
      .map(maskS2clouds)
      .map(addNBR);
    const size1b = col1.size().getInfo();
    console.log(`Jan 6 Extended Images: ${size1b}`);
    if (size1b === 0) {
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // Get Sentinel-2 data for January 14, 2025
  let col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(areaOfInterest)
    .filterDate('2025-01-13', '2025-01-15')
    .map(maskS2clouds)
    .map(addNBR);

  const size2 = col2.size().getInfo();
  console.log(`Jan 14 Images: ${size2}`);

  if (size2 === 0) {
    col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(areaOfInterest)
      .filterDate('2025-01-12', '2025-01-16')
      .map(maskS2clouds)
      .map(addNBR);
    const size2b = col2.size().getInfo();
    console.log(`Jan 14 Extended Images: ${size2b}`);
    if (size2b === 0) {
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // Create median composites
  const img1 = col1.median();
  const img2 = col2.median();

  // Count valid pixels for both dates
  const count1 = img1.select('NBR').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: areaOfInterest,
    scale: 3000,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  const count2 = img2.select('NBR').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: areaOfInterest,
    scale: 3000,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  console.log(`Jan 6 Valid Pixels: ${count1}`);
  console.log(`Jan 14 Valid Pixels: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // Calculate burned area (NBR < 0.1 threshold)
  const burnThreshold = 0.1;
  const burned1 = img1.select('NBR').lt(burnThreshold);
  const burned2 = img2.select('NBR').lt(burnThreshold);

  // Calculate burned pixel counts
  const burnedArea1 = burned1.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: areaOfInterest,
    scale: 3000,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  const burnedArea2 = burned2.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: areaOfInterest,
    scale: 3000,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  console.log(`Jan 6 Burned Pixels: ${burnedArea1}`);
  console.log(`Jan 14 Burned Pixels: ${burnedArea2}`);

  if (burnedArea1 === null || burnedArea2 === null) {
    console.log('<answer>C3</answer>');
    return;
  }

  if (burnedArea2 > burnedArea1) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
